//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.url;
scwin.chk;
scwin.vScrenID = "ULDSTF30000_POP.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

//데이타 가져와서 뿌리기 List
scwin.fn_list_sync = function() {
    var url = "/DisclosureSchedule.do?method=listScheduleClose";
    scwin.url += "&EMP_NO=" + js_emp_no; //사원번호
    scwin.url += "&BELNG_DEP_CD=" + js_belngdepcd; //상위부서코드
    scwin.url += "&DEP_CD=" + js_dep_cd; //부서코드
    scwin.url += "&SCREN_ID=" + scwin.vScrenID;
    scwin.url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    //코스닥당번이면 
    if (js_duty == "Y" || js_duty_chrg == "Y") {
        //if(js_emp_no == "adm040"){
        scwin.url += "&DUTY=Y"; //당번여부 (Y, N)

    } else {
        scwin.url += "&DUTY=N"; //당번여부 (Y, N)

    }
    scwin.url += "&JOB_TITLE=" + js_jobtitl; //직책구분 여부 - 03:담당자, 09:책임자
    scwin.url += "&TODATE=" + $c.ut.cGetToday2(); //날짜
    //url += "&TODATE=20090901" ;					//날짜

    dts_List.DataID = encodeURI(scwin.url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List);
};


//저장
scwin.fn_Save = async function() {
    var conYN = "Y"; //확정여부  확인		
    var reYN = "Y"; //진행여부 확인

    //alert("dts_List.CountRow-->"+dts_List.CountRow);		

    //확정 체크
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        //alert("확정여부-->"+dts_List.NameValue(i, "TOTAL_SCHDL_CONFRM_YN")+"---"+ i );			
        if (dts_List.getCellData(i, "TOTAL_SCHDL_CONFRM_YN") == "N") {
            conYN = "N";
            $c.win.alert("담당자 확인이 되지 않은 일정이 있습니다.\n담당자 확인을 먼저 해주시기 바랍니다.");
            await $c.frame.CloseFrame();
            return false;
        } else {
            conYN = "Y";
        }
    }

    //책임자 또는 당번이 마감을 할 경우 담당자 또는 팀이 마감이 안되어 있을때 본인(책임자,당번)이 마감을 못하도록 막는다.
    //당번 마감은 모든 공시팀이 마감을 했을 경우에 가능
    //책임자 마감은 해당 팀 담당자가 모두 마감을 했을 경우에 가능.
    if (dts_List.getTotalRow() > 1) {
        for (var i = 2; i <= dts_List.getTotalRow(); i++) {
            //alert("CLS_YN-->"+dts_List.NameValue(i, "CLS_YN")+"---"+ i );				
            if (dts_List.getCellData(i, "CLS_YN") == "N") {
                reYN = "N";
                $c.win.alert("진행중인 담당자 또는 팀이 있습니다.\n진행건을 먼저 마감 해주시기 바랍니다.");
                return false;
            }
        }
    }
    if (conYN == "Y") {
        if (reYN == "Y") {
            var res = window.confirm("[저장]하시겠습니까?");
            if (res) {
                trs_Save.Action = "/DisclosureSchedule.do?method=modifyScheduleClose&EMP_NO=" + js_emp_no + "&JOB_TITLE=" + js_jobtitl + "&DUTY=" + js_duty + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
                trs_Save.KeyName = "toinb_dataid4";
                trs_Save.KeyValue = "JSP(I:pInput=dts_List)";
                trs_Save.Post();
            }
        }
    }
};





//콤보박스의 상태변경(진행, 마감)
scwin.fn_chkEnd = function(row, colid) {
    /*
    alert("NameValue--"+dts_List.NameValue(row, colid));
    alert("NameString-->"+dts_List.NameString(row, colid));

    alert("chk-->"+chk);

    if(chk != dts_List.NameString(row, colid)){
    	if(chk == "Y"){
    */
    if (dts_List.getCellData(row, colid) == "N") {
        $c.win.alert("이미 마감 된것은 변경할 수 없습니다.");
        dts_List.setCellData(row, colid, "Y");
    }
    /*		
    	}
    }
    */
};







//콤보의 변경전 값을 저장
scwin.fn_chkClick = function(row, colid) {
    scwin.chk = dts_List.getCellData(row, colid);
};
scwin.grd_List_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    //alert("rowCnt-->"+rowcount);

    //alert("dts_List.CountRow-->"+dts_List.CountRow);

};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.grd_List_OnCloseUp = function(row, colid) {
    scwin.fn_chkEnd(row, colid);
};
scwin.grd_List_OnDropDown = function(row, colid) {
    scwin.fn_chkClick(row, colid);
};
scwin.btn_input_onclick = function() {
    scwin.fn_Save();
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "저장"));
    $c.win.alert(trs_Save.ErrorMsg);
};
scwin.gform_onload = function() {
    scwin.fn_list_sync();
};
